/* GUItober archive — app
 * All content comes from window.GUITOBER (assets/js/data.js, generated by tools/build.py
 * from content/). Nothing here needs editing to add a year, participant or work.
 * Routes (hash based, so the site works on any static host and from file://):
 *   #/2025/days[/05]   #/2025/participants[/podusenko]   #/2025/prompts[/05]   #/2025/rules
 */
(() => {
  'use strict';
  const D = window.GUITOBER;

  /* ------------------------------------------------------------ edit mode (index.html?edit)
     Lets the organiser fix days / remove works right on the site. Changes live in this browser
     (localStorage) and are exported as edits.json → tools/apply_edits.py writes them to works.json. */
  const EDIT = /[?&]edit\b/.test(location.search);
  const EDIT_KEY = 'guitober-edits';
  const ORIG = {};
  let EDITS = {};
  if (EDIT) { try { EDITS = JSON.parse(localStorage.getItem(EDIT_KEY) || '{}'); } catch (e) { EDITS = {}; } }
  function applyEdits() {
    for (const y in D.years) for (const w of D.years[y].works) {
      if (!(w.id in ORIG)) ORIG[w.id] = [...w.days];
      const e = EDITS[y] && EDITS[y][w.id];
      w.days = e && e.days ? [...e.days] : [...ORIG[w.id]];
      w.removed = !!(e && e.remove);
    }
  }
  // drop saved edits that are already applied to the data (work gone, or days already match)
  function pruneEdits() {
    for (const y of Object.keys(EDITS)) {
      const ids = new Map((D.years[y] ? D.years[y].works : []).map(w => [w.id, w]));
      for (const id of Object.keys(EDITS[y])) {
        const w = ids.get(id), e = EDITS[y][id];
        if (!w) { delete EDITS[y][id]; continue; }
        if (e.days && [...e.days].sort((a, b) => a - b).join() === [...w.days].sort((a, b) => a - b).join()) delete e.days;
        if (!e.days && !e.remove) delete EDITS[y][id];
      }
      if (!Object.keys(EDITS[y]).length) delete EDITS[y];
    }
    try { localStorage.setItem(EDIT_KEY, JSON.stringify(EDITS)); } catch (err) {}
  }
  if (EDIT) { pruneEdits(); applyEdits(); }
  const $ = (s, el = document) => el.querySelector(s);
  const LANG = 'ru';
  const T = D.site.ui[LANG];
  const SECTIONS = ['days', 'participants', 'prompts', 'rules'];

  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const pad2 = n => String(n).padStart(2, '0');
  const plural = (n, forms) => {
    const a = Math.abs(n) % 100, b = a % 10;
    return forms[a > 10 && a < 20 ? 2 : b > 1 && b < 5 ? 1 : b === 1 ? 0 : 2];
  };
  const collator = new Intl.Collator('ru', { sensitivity: 'base' });

  /* ------------------------------------------------------------ derived data per year */
  const cache = {};
  function yearData(y) {
    if (cache[y]) return cache[y];
    const cfg = D.years[y];
    const works = cfg.works.filter(w => EDIT || !w.removed);
    const byAuthor = new Map();
    for (const w of works) {
      if (!byAuthor.has(w.author)) byAuthor.set(w.author, { works: [], days: new Set() });
      const a = byAuthor.get(w.author);
      a.works.push(w);
      if (!w.removed) w.days.forEach(d => a.days.add(d));
    }
    const min = cfg.minPromptsToPublish ?? 0;
    const medals = [...(cfg.medals || [])].sort((a, b) => a.min - b.min);
    const prompts = new Map((cfg.prompts || []).map(p => [p.day, p]));
    // days without a prompt of their own (e.g. 18 «Рефакторинг»): no works are shown there
    const noWorkDays = new Set((cfg.prompts || []).filter(p => p.noWorks).map(p => p.day));
    for (const w of works) w.shownDays = w.days.filter(d => !noWorkDays.has(d));

    // every author who posted works in the chat
    const authors = [];
    for (const [id, a] of byAuthor) {
      const count = a.days.size;               // closed prompts, not files
      const person = D.people[id] || { id, name: id, telegram: id };
      const published = count >= min;         // got to the threshold → own section + medal
      const override = cfg.medalOverrides?.[id];
      const medal = !published ? null : override ? medals.find(m => m.id === override)
                             : [...medals].reverse().find(m => count >= m.min);
      authors.push({ id, person, count, days: a.days, works: a.works, medal, published });
    }
    // rank: participants first, then everybody else; more prompts first; stable tie-break by name, then id
    authors.sort((a, b) => (b.published - a.published) || b.count - a.count || collator.compare(a.person.name, b.person.name) || a.id.localeCompare(b.id));
    authors.forEach((p, i) => { p.order = i; });
    const participants = authors.filter(a => a.published);
    participants.forEach((p, i) => { p.rank = i + 1; });
    const amap = new Map(authors.map(p => [p.id, p]));
    const pmap = new Map(participants.map(p => [p.id, p]));

    const byDay = new Map();
    for (const w of works) for (const d of w.shownDays) {
      if (!byDay.has(d)) byDay.set(d, []);
      byDay.get(d).push(w);
    }
    for (const list of byDay.values()) list.sort((a, b) => amap.get(a.author).order - amap.get(b.author).order || a.id.localeCompare(b.id));
    const shownWorks = works.filter(w => w.shownDays.length && !w.removed);
    // works not yet assigned to any day — shown at the bottom of «По дням» for manual sorting
    const unsorted = works.filter(w => !w.days.length)
      .sort((a, b) => amap.get(a.author).order - amap.get(b.author).order || a.id.localeCompare(b.id));
    return (cache[y] = { cfg, authors, amap, participants, pmap, byDay, prompts, shownWorks, unsorted, medals, noWorkDays });
  }

  /* ------------------------------------------------------------ tiny markdown */
  function inline(s) {
    const keep = [];
    s = esc(s).replace(/\\([\\*`\[\]~_])/g, (_, c) => `\u0000${keep.push(c) - 1}\u0000`);
    s = s.replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_, t, u) => `<a href="${u}" target="_blank" rel="noopener">${t}</a>`)
      .replace(/(^|[\s(])(https?:\/\/[^\s<)]+)/g, '$1<a href="$2" target="_blank" rel="noopener">$2</a>')
      .replace(/\*\*([^*]+?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*([^*\n]+?)\*/g, '<em>$1</em>')
      .replace(/~~([^~]+?)~~/g, '<s>$1</s>');
    return s.replace(/\u0000(\d+)\u0000/g, (_, i) => esc(keep[i]));
  }
  /* Markdown-lite for Telegram texts: paragraphs (line breaks kept), headings, quotes,
     numbered lists that keep their original numbers even when items are separated by blank lines,
     bullet lists (-, ⁃, •) and bullets nested under a numbered item. */
  function md(src) {
    if (!src) return '';
    const lines = src.replace(/\r/g, '').trim().split('\n');
    const out = [];
    let para = [], quote = [], ol = null, ul = null, li = null, blank = false;
    const flushPara = () => { if (para.length) { out.push(`<p>${para.map(inline).join('<br>')}</p>`); para = []; } };
    const flushQuote = () => { if (quote.length) { out.push(`<blockquote>${quote.map(inline).join('<br>')}</blockquote>`); quote = []; } };
    const closeUl = () => {
      if (!ul) return;
      const h = `<ul>${ul.items.map(x => `<li>${x}</li>`).join('')}</ul>`;
      if (ul.nested && li) li.html += h; else out.push(h);
      ul = null;
    };
    const closeOl = () => {
      closeUl();
      if (ol) out.push(`<ol>${ol.map(i => `<li value="${i.n}">${i.html}</li>`).join('')}</ol>`);
      ol = null; li = null;
    };
    const closeAll = () => { flushPara(); flushQuote(); closeOl(); closeUl(); };
    for (const raw of lines) {
      const l = raw.replace(/\s+$/, '');
      let m;
      if (!l.trim()) { flushPara(); flushQuote(); blank = true; continue; }
      if ((m = l.match(/^(#{1,3})\s+(.+)$/))) {
        closeAll(); const h = Math.min(3, m[1].length + 1); out.push(`<h${h}>${inline(m[2])}</h${h}>`);
      } else if (l.startsWith('>')) {
        flushPara(); closeOl(); closeUl(); quote.push(l.replace(/^>\s?/, ''));
      } else if ((m = l.match(/^\s*(\d{1,2})[.)]\s+(.*)$/))) {
        flushPara(); flushQuote(); closeUl();
        if (!ol) ol = [];
        li = { n: +m[1], html: inline(m[2]) }; ol.push(li);
      } else if ((m = l.match(/^(\s*)[-⁃•–]\s+(.*)$/))) {
        flushPara(); flushQuote();
        const nested = !!ol && (m[1].length > 0 || !blank);
        if (!nested && ol) closeOl();
        if (ul && ul.nested !== nested) closeUl();
        if (!ul) ul = { items: [], nested };
        ul.items.push(inline(m[2]));
      } else {
        flushQuote();
        if ((ol || ul) && !blank) {                 // continuation of the last list item
          if (ul) ul.items[ul.items.length - 1] += '<br>' + inline(l.trim());
          else li.html += '<br>' + inline(l.trim());
        } else {
          closeOl(); closeUl(); para.push(l.trim());
        }
      }
      blank = false;
    }
    closeAll();
    return out.join('\n');
  }


  /* ------------------------------------------------------------ bits */
  const AV_COLORS = ['#FF845E', '#FEBB5B', '#B694F9', '#9AD164', '#5BCBE3', '#5CAFFA', '#FF8AAC'];
  function initials(name, id) {
    const words = String(name || '').replace(/[^\p{L}\p{N}\s]/gu, ' ').trim().split(/\s+/).filter(Boolean);
    let s = words.slice(0, 2).map(w => w[0]).join('');
    if (!s) s = String(id || '?').replace(/[^\p{L}\p{N}]/gu, '').slice(0, 1);
    return s.toUpperCase();
  }
  function hash(s) { let h = 0; for (const c of String(s)) h = (h * 31 + c.codePointAt(0)) >>> 0; return h; }
  function avatar(person, small) {
    const cls = 'avatar' + (small ? ' avatar--s' : '');
    if (person.avatar) return `<span class="${cls}"><img src="${esc(person.avatar)}" alt="" loading="lazy"></span>`;
    const c1 = AV_COLORS[hash(person.id) % AV_COLORS.length];
    return `<span class="${cls}" style="background:linear-gradient(160deg, ${c1}cc, ${c1})" aria-hidden="true">${esc(initials(person.name, person.id))}</span>`;
  }
  function personLinks(person, withLink = true) {
    const out = [];
    if (person.telegram) out.push(`<a href="https://t.me/${encodeURIComponent(person.telegram)}" target="_blank" rel="noopener">@${esc(person.telegram)}</a>`);
    else if (person.discord) out.push(`<span class="discord" title="Ник в Discord">Discord: ${esc(person.discord)}</span>`);
    // one link (person.link) or several (person.links: [{label, url}, …])
    const ls = !withLink ? [] : person.links?.length ? person.links : person.link ? [person.link] : [];
    for (const l of ls) {
      if (l.url) out.push(`<a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label || 'Ссылка')} ↗</a>`);
      else out.push(`<span class="placeholder" title="Ссылка ещё не добавлена">${esc(l.label || 'Ссылка')} ↗</span>`);
    }
    return out.join('');
  }
  const ICON = {
    play: '<svg viewBox="0 0 10 10"><path d="M2 1l7 4-7 4z" fill="currentColor"/></svg>',
    close: '<svg viewBox="0 0 16 16"><path d="M2 2l12 12M14 2L2 14" stroke="currentColor" stroke-width="1.5"/></svg>',
    prev: '<svg viewBox="0 0 16 16"><path d="M10 2L4 8l6 6" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>',
    next: '<svg viewBox="0 0 16 16"><path d="M6 2l6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>',
  };

  /* ------------------------------------------------------------ masonry (Pinterest-like, order left→right) */
  const galleries = [];
  function colsFor(width) {
    if (width < 520) return 2;
    if (width < 900) return 3;
    if (width < 1400) return 4;
    if (width < 2000) return 5;
    return 6;
  }
  function tile(w, ctx, idx) {
    const alt = `${(D.people[w.author] || {}).name || w.author}`;
    const multi = w.shownDays.length > 1 ? `<span class="badge days">${w.shownDays.map(pad2).join(' · ')}</span>` : '';
    const vid = w.type === 'video' ? `<span class="badge">${ICON.play}видео</span>` : '';
    const ed = EDIT ? `<span class="editlabel">${esc((w.file || '').split('/').pop())} · ${w.days.map(pad2).join(',') || '—'}</span>` : '';
    return `<button class="tile${EDIT && w.removed ? ' is-removed' : ''}" data-ctx="${ctx}" data-i="${idx}" aria-label="${esc(alt)}">
      <img src="${esc(w.thumb)}" width="${w.w}" height="${w.h}" alt="${esc(alt)}" loading="lazy" decoding="async">${vid}${multi}${ed}</button>`;
  }
  function layout(g) {
    const n = colsFor(g.el.clientWidth || window.innerWidth);
    if (g.cols === n && g.el.childElementCount) return;
    g.cols = n;
    const heights = new Array(n).fill(0);
    const cols = Array.from({ length: n }, () => []);
    g.items.forEach((w, i) => {
      let k = 0;
      for (let j = 1; j < n; j++) if (heights[j] < heights[k] - 0.02) k = j;
      cols[k].push(tile(w, g.ctx, i));
      heights[k] += (w.h / w.w) || 1;
    });
    g.el.innerHTML = cols.map(c => `<div class="masonry__col">${c.join('')}</div>`).join('');
  }
  function gallery(items) {
    const ctx = galleries.length;
    galleries.push({ ctx, items, el: null, cols: 0 });
    return `<div class="masonry" data-gallery="${ctx}"></div>`;
  }
  function mountGalleries(root) {
    root.querySelectorAll('[data-gallery]').forEach(el => {
      const g = galleries[+el.dataset.gallery];
      g.el = el; layout(g);
    });
  }
  let rT;
  window.addEventListener('resize', () => { clearTimeout(rT); rT = setTimeout(() => galleries.forEach(g => g.el && layout(g)), 120); });

  /* ------------------------------------------------------------ chrome */
  function applyYearTheme(cfg) {
    const r = document.documentElement.style;
    const f = cfg.font || {};
    r.setProperty('--year', cfg.color || '#111');
    r.setProperty('--year-text', cfg.colorText || '#fff');
    r.setProperty('--accent', cfg.accent || cfg.color || '#111');
    r.setProperty('--display', f.family ? `"${f.family}", ${f.fallback || 'sans-serif'}` : 'Georgia, serif');
    r.setProperty('--dw', f.weight || 400);
    r.setProperty('--dstretch', f.stretch || '100%');
    r.setProperty('--logo-scale', cfg.logoScale ?? 1);
  }
  function renderTopbar(year, section) {
    const years = D.site.years.map(y => `<a class="pill" href="#/${y}/${section}" ${y === year ? 'aria-current="page"' : ''}>${y}</a>`).join('');
    const langs = D.site.languages.map(l => l.code === LANG
      ? `<a class="pill" href="#" aria-current="page" onclick="return false">${l.label}</a>`
      : `<span aria-disabled="${!l.enabled}" title="Скоро">${l.label}</span>`).join('');
    $('#topbar').innerHTML = `<nav aria-label="Годы">${years}</nav>
      <nav aria-label="Язык и контакты"><span class="lang">${langs}</span>
      <a class="contact" href="${esc(D.site.contacts.url)}" target="_blank" rel="noopener">${T.contacts}</a></nav>`;
  }
  function renderYearhead(year, section) {
    const Y = yearData(year), cfg = Y.cfg;
    const nWorks = Y.shownWorks.length;
    // everyone who posted at least one work counts here (the Participants section only lists those with 7+ prompts)
    const nPeople = Y.authors.filter(a => a.works.some(w => !w.removed)).length;
    // works are shown approximately: rounded up to the next ten (397 → ~400, 370 → ~370)
    const approx = Math.ceil(nWorks / 10) * 10;
    const stat = (num, label, tilde) => `<div class="stat"><span class="stat__num">${tilde ? '<span class="stat__tilde">~</span>' : ''}${num}</span><span class="stat__label">${label}</span></div>`;
    const meta = cfg.status === 'upcoming'
      ? `<b>${esc(cfg.dates)}</b><br>скоро старт`
      : stat(nPeople, plural(nPeople, T.participants)) + stat(approx, plural(approx, ['опубликованная работа', 'опубликованные работы', 'опубликованных работ']), true);
    $('#yearhead').innerHTML = `
      <div class="yearhead__top">
        <h1><img class="yearhead__logo" src="${esc(cfg.logo)}" alt="${esc(cfg.title)}"></h1>
        <div class="yearhead__meta${cfg.status === 'upcoming' ? '' : ' yearhead__meta--stats'}">${meta}</div>
      </div>`;
    $('#yearhead').classList.toggle('yearhead--bleed', !!cfg.logoBleed);
    const logo = $('.yearhead__logo');
    const setAR = () => logo.naturalWidth && document.documentElement.style.setProperty('--logo-ar', logo.naturalWidth / logo.naturalHeight);
    logo.complete ? setAR() : logo.addEventListener('load', setAR, { once: true });
    $('#secbar').innerHTML = `<nav class="sections" aria-label="Разделы">
      <a class="sections__logo" href="#top" data-totop aria-label="Наверх" tabindex="-1"><img src="${esc(cfg.logoMini || cfg.logo)}" alt=""></a>
      ${SECTIONS.map(s => (cfg.disabledSections || []).includes(s)
        ? `<span aria-disabled="true" title="Скоро">${T.nav[s]}</span>`
        : `<a href="#/${year}/${s}" ${s === section ? 'aria-current="page"' : ''}>${T.nav[s]}</a>`).join('')}</nav>`;
  }

  /* sticky section bar: mini logo shows once the bar reaches the top */
  const secbar = $('#secbar');
  new IntersectionObserver(([e]) => {
    const stuck = !e.isIntersecting && e.boundingClientRect.top < 60;
    secbar.classList.toggle('is-stuck', stuck);
    const l = $('.sections__logo', secbar); if (l) l.tabIndex = stuck ? 0 : -1;
  }, { rootMargin: '-45px 0px 0px 0px' }).observe($('#secbar-sentinel'));
  secbar.addEventListener('click', e => {
    if (!e.target.closest('[data-totop]')) return;
    e.preventDefault();
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });

  function renderFooter() {
    const f = D.site.footer;
    const now = Math.max(...D.site.years.map(Number));
    $('#footer').innerHTML = `<div class="footer__inner">
      <div class="footer__logos">${f.logos.map(l => `<a href="${esc(l.url)}" target="_blank" rel="noopener"><img src="${esc(l.image)}" alt="${esc(l.alt)}"></a>`).join('')}</div>
      <div class="footer__text">${(f.links || []).map(l => `<a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label)}</a>`).join('')}
        <div>© ${f.since}–${now} ${esc(f.copyright)}</div></div></div>`;
  }

  /* ------------------------------------------------------------ views */
  function viewDays(year) {
    const Y = yearData(year), cfg = Y.cfg;
    const days = [...Y.prompts.keys()].sort((a, b) => a - b);
    const jump = `<nav class="dayjump" aria-label="Дни">${days.map(d =>
      `<a href="#/${year}/days/${pad2(d)}" class="${Y.byDay.get(d)?.length ? '' : 'is-empty'}">${pad2(d)}</a>`).join('')}${
      Y.unsorted.length ? `<a href="#/${year}/days/none" class="is-none">${T.noPrompt}</a>` : ''}</nav>`;
    const upcoming = cfg.status === 'upcoming' ? `<p class="empty">${T.upcoming}</p>` : '';
    const blocks = days.map(d => {
      const p = Y.prompts.get(d);
      const list = Y.byDay.get(d) || [];
      const title = p.secret ? `<span class="secret">${T.secret}</span>` : esc(p.title);
      const en = p.titleEn && !p.secret && p.titleEn.toLowerCase() !== p.title.toLowerCase() ? `<span class="en">${esc(p.titleEn)}</span>` : '';
      const link = p.text ? `<a href="#/${year}/prompts/${pad2(d)}">${T.toPrompt}</a>` : '';
      const meta = cfg.status === 'upcoming' ? ''
        : p.noWorks ? (link ? `<div class="day__meta">${link}</div>` : '')
        : `<div class="day__meta">${list.length} ${plural(list.length, T.works)}${link ? ' · ' + link : ''}</div>`;
      const body = list.length ? gallery(list)
        : cfg.status === 'upcoming' ? ''
        : `<p class="lead">${p.noWorks ? (T.noWorksDay || T.noWorks) : T.noWorks}</p>`;
      return `<section class="day" id="d-${pad2(d)}"><div class="day__head"><span class="num">${pad2(d)}</span>
        <h2 class="day__title">${title}${en}</h2>${meta}</div>${body}</section>`;
    }).join('');
    const chat = D.site.communityChat;
    const head = `<h2 class="page-title">${T.daysTitle}</h2>
      <p class="page-sub">${T.daysSub}${chat ? ` <a href="${esc(chat.url)}" target="_blank" rel="noopener">${esc(chat.label)}</a>` : ''}</p>`;
    const none = Y.unsorted.length ? `<section class="day day--none" id="d-none"><div class="day__head">
        <h2 class="day__title">${T.noPrompt}</h2><div class="day__meta">${Y.unsorted.length} ${plural(Y.unsorted.length, T.works)}</div></div>
        ${gallery(Y.unsorted)}</section>` : '';
    return head + jump + upcoming + blocks + none;
  }

  // special highlight inside a participant's block (year.json → features.<id>: {image, text, links})
  function featureBlock(f) {
    if (!f) return '';
    const links = (f.links || []).map(l => `<a href="${esc(l.url)}" target="_blank" rel="noopener">${esc(l.label)}</a>`).join('');
    return `<div class="feature">
      ${f.image ? (f.imageUrl
        ? `<a class="feature__imglink" href="${esc(f.imageUrl)}" target="_blank" rel="noopener"><img class="feature__img" src="${esc(f.image)}" alt="" loading="lazy"></a>`
        : `<img class="feature__img" src="${esc(f.image)}" alt="" loading="lazy">`) : ''}
      <div class="feature__body"><div class="feature__text">${md(f.text || '')}</div>
        ${links ? `<div class="feature__links">${links}</div>` : ''}</div></div>`;
  }

  function viewParticipants(year) {
    const Y = yearData(year), cfg = Y.cfg;
    const medalCount = m => Y.participants.filter(p => p.medal && p.medal.id === m.id).length;
    const legend = Y.medals.length ? `<div class="medals-legend">${Y.medals.map(m =>
      `<div><img src="${esc(m.image)}" alt=""><span><b>${esc(m.title)}</b>от ${m.min} ${plural(m.min, T.promptsFrom)} · ${medalCount(m)} ${plural(medalCount(m), ['человек', 'человека', 'человек'])}</span></div>`).join('')}</div>` : '';
    if (!Y.participants.length) return legend + `<p class="empty">${T.upcoming}</p>`;
    const total = Y.prompts.size || 31;
    return legend + Y.participants.map(p => {
      const cells = Array.from({ length: total }, (_, i) => `<i class="${p.days.has(i + 1) ? 'on' : ''}" title="${pad2(i + 1)}"></i>`).join('');
      const works = [...p.works].sort((a, b) => (a.days[0] ?? 99) - (b.days[0] ?? 99) || a.id.localeCompare(b.id));
      return `<section class="person" id="p-${esc(p.id)}">
        <div class="person__head">
          ${avatar(p.person)}
          <div><div class="person__rank">№ ${p.rank}</div><h2 class="person__name">${esc(p.person.name)}</h2>
            <div class="person__links">${personLinks(p.person)}</div></div>
          <div class="person__side">
            <div class="person__score"><b>${p.count}</b>${plural(p.count, T.promptsDone)} ${T.of} ${total}
              ${p.medal ? `<span class="mt">${esc(p.medal.title)}</span>` : ''}
              <div class="progress" aria-hidden="true">${cells}</div></div>
            ${p.medal ? `<span class="medal-hint" data-hint="${esc(p.medal.title)}"><img class="medal" src="${esc(p.medal.image)}" alt="${esc(p.medal.title)}"></span>` : ''}
          </div>
        </div>${featureBlock(cfg.features?.[p.id])}${gallery(works)}</section>`;
    }).join('');
  }

  function viewPrompts(year) {
    const Y = yearData(year), cfg = Y.cfg;
    const list = [...Y.prompts.values()].sort((a, b) => a.day - b.day);
    // text list of all prompts (replaces the Telegram picture): muted day numbers, weekends in the accent colour,
    // columns 1→4 by screen width, filled top-to-bottom like on the original picture
    const isWeekend = d => { const w = new Date(+year, 9, d).getDay(); return w === 0 || w === 6; };
    const index = `<h2 class="page-title">${T.promptsTitle}</h2><ol class="plist" aria-label="${T.promptsTitle}">${list.map(p =>
      `<li class="plist__item${isWeekend(p.day) ? ' is-weekend' : ''}"><a href="#/${year}/prompts/${pad2(p.day)}">
        <span class="plist__num">${p.day}</span><span class="plist__title${p.secret ? ' secret' : ''}">${p.secret ? T.secret : esc(p.title)}</span></a></li>`).join('')}</ol>`;
    return index + list.map(p => {
      const title = p.secret ? `<span class="secret">${T.secret}</span>` : esc(p.title);
      const en = p.titleEn && !p.secret && p.titleEn.toLowerCase() !== p.title.toLowerCase() ? `<span class="en">${esc(p.titleEn)}</span>` : '';
      const n = Y.byDay.get(p.day)?.length || 0;
      const text = p.secret ? `<p>${T.secretText}</p>` : (p.text ? md(p.text) : `<p style="color:var(--muted)">Описание промпта появится в день публикации.</p>`);
      return `<section class="prompt" id="d-${pad2(p.day)}">
        <div class="prompt__head"><span class="num">${pad2(p.day)}</span><h2 class="day__title">${title}${en}</h2>
          ${n ? `<a class="jump" href="#/${year}/days/${pad2(p.day)}">${n} ${plural(n, T.works)} →</a>` : ''}
          ${p.image ? `<img class="wire" src="${esc(p.image)}" alt="" loading="lazy">` : ''}</div>
        <div class="prose">${text}</div></section>`;
    }).join('');
  }

  function viewRules(year) {
    const cfg = yearData(year).cfg;
    const html = md(cfg.rulesText)
      // hashtags → accent colour (plain text, not links)
      .replace(/(^|[\s>(])(#[\p{L}\p{N}_]+)/gu, '$1<span class="tag">$2</span>')
      // footnote star in the list and the footnote paragraph below it
      .replace(/\*<\/li>/g, '<span class="star">*</span></li>')
      .replace(/<p>\*\s*/g, '<p class="footnote"><span class="star">*</span> ');
    const images = (cfg.rulesImages || []).map(src => `<img src="${esc(src)}" alt="" loading="lazy">`).join('');
    // optional second column text (year.json → rulesAside) and an accent-framed note under the rules (rulesNote)
    const aside = cfg.rulesAsideText ? `<div class="rules__aside">${md(cfg.rulesAsideText)}</div>` : '';
    const note = cfg.rulesNoteText ? `<div class="rules__note">${md(cfg.rulesNoteText)}</div>` : '';
    const side = aside || images ? `<div class="rules__side">${aside}${images ? `<div class="rules__images">${images}</div>` : ''}</div>` : '';
    return `<h2 class="page-title">${T.rulesTitle}</h2>
      <div class="rules${side ? '' : ' rules--single'}"><div class="prose">${html}</div>${side}</div>${note}`;
  }


  /* ------------------------------------------------------------ modal */
  const modal = $('#modal');
  let current = null, lastFocus = null;
  function openWork(ctx, i) {
    const g = galleries[ctx];
    if (!g) return;
    current = { g, i: (i + g.items.length) % g.items.length };
    const w = current.g.items[current.i];
    const Y = yearData(route.year);
    const p = Y.amap.get(w.author);
    const person = p.person;
    const media = w.type === 'video'
      ? `<video src="${esc(w.video)}" poster="${esc(w.thumb)}" controls autoplay muted loop playsinline></video>`
      : `<img src="${esc(w.full)}" alt="${esc(person.name)}" width="${w.w}" height="${w.h}" style="background-image:url('${esc(w.thumb)}');background-size:cover">`;
    const chips = w.shownDays.map(d => {
      const pr = Y.prompts.get(d);
      return `<a class="chip" href="#/${route.year}/days/${pad2(d)}"><b>${pad2(d)}</b>${pr && !pr.secret ? esc(pr.title) : ''}</a>`;
    }).join('');
    modal.innerHTML = `
      <div class="modal__head">
        <div class="modal__author">${avatar(person, true)}<div>
          <div class="nm">${p.published ? `<a href="#/${route.year}/participants/${esc(p.id)}" style="text-decoration:none">${esc(person.name)}</a>` : esc(person.name)}</div>
          <div class="ln">${personLinks(person, p.published)}</div></div></div>
        <div class="modal__right">
          ${p.medal ? `<div class="modal__medal"><span>${esc(p.medal.title)}<br>${p.count} ${plural(p.count, T.promptsDone)}</span><img src="${esc(p.medal.image)}" alt="${esc(p.medal.title)}"></div>` : ''}
          <button class="iconbtn" data-close aria-label="${T.close}">${ICON.close}</button>
        </div>
      </div>
      <div class="modal__stage" data-stage>
        ${media}
        ${g.items.length > 1 ? `<button class="iconbtn nav prev" data-prev aria-label="${T.prev}">${ICON.prev}</button>
        <button class="iconbtn nav next" data-next aria-label="${T.next}">${ICON.next}</button>` : ''}
      </div>
      <div class="modal__foot"><span class="lbl">${w.shownDays.length ? (w.shownDays.length > 1 ? 'Промпты' : T.prompt) : T.extra}</span>${chips}
        <span class="modal__count">${current.i + 1} / ${g.items.length}</span></div>${EDIT ? editPanel(w) : ''}`;
    modal.classList.toggle('modal--edit', EDIT);
    if (modal.hidden) {
      lastFocus = document.activeElement;
      modal.hidden = false;
      document.body.classList.add('is-locked');
    }
    $('[data-close]', modal).focus({ preventScroll: true });
  }
  function closeModal() {
    if (modal.hidden) return;
    modal.hidden = true; modal.innerHTML = '';
    document.body.classList.remove('is-locked');
    current = null;
    if (editDirty) { editDirty = false; rerenderView(); }
    else if (lastFocus) lastFocus.focus({ preventScroll: true });
  }

  /* edit mode: panel in the popup + bottom bar with export */
  let editDirty = false;
  function editPanel(w) {
    const days = Array.from({ length: 31 }, (_, i) => i + 1).map(d =>
      `<button data-eday="${d}" class="${w.days.includes(d) ? 'on' : ''}${ORIG[w.id].includes(d) ? ' orig' : ''}">${pad2(d)}</button>`).join('');
    const changed = EDITS[route.year] && EDITS[route.year][w.id];
    return `<div class="editpanel">
      <div class="editpanel__file">${esc(w.id)} · ${esc(w.file || '')}${changed ? ' · <b>изменено</b>' : ''}</div>
      <div class="editpanel__days">${days}</div>
      <div class="editpanel__actions"><button data-eremove class="${w.removed ? 'on' : ''}">${w.removed ? 'Вернуть работу' : 'Удалить работу'}</button>
        ${changed ? '<button data-ereset>Отменить правки этой работы</button>' : ''}</div></div>`;
  }
  function editWork(w, btn) {
    const y = route.year;
    EDITS[y] = EDITS[y] || {};
    const e = Object.assign({}, EDITS[y][w.id]);
    if (btn.dataset.eday) {
      const d = +btn.dataset.eday;
      const days = new Set(w.days); days.has(d) ? days.delete(d) : days.add(d);
      const arr = [...days].sort((a, b) => a - b);
      if (arr.join() === [...ORIG[w.id]].sort((a, b) => a - b).join()) delete e.days; else e.days = arr;
    } else if (btn.hasAttribute('data-eremove')) {
      if (w.removed) delete e.remove; else e.remove = true;
    } else if (btn.hasAttribute('data-ereset')) {
      delete e.days; delete e.remove;
    }
    if (Object.keys(e).length) EDITS[y][w.id] = e; else delete EDITS[y][w.id];
    if (!Object.keys(EDITS[y]).length) delete EDITS[y];
    try { localStorage.setItem(EDIT_KEY, JSON.stringify(EDITS)); } catch (err) {}
    applyEdits(); delete cache[y]; yearData(y);   // recompute shownDays for the open work
    editDirty = true;
    openWork(current.g.ctx, current.i);
    renderEditBar();
  }
  function editsJSON() { return JSON.stringify(EDITS, null, 2); }
  function renderEditBar() {
    if (!EDIT) return;
    let bar = $('#editbar');
    if (!bar) { bar = document.createElement('div'); bar.id = 'editbar'; bar.className = 'editbar'; document.body.appendChild(bar); }
    const n = Object.values(EDITS).reduce((s, y) => s + Object.keys(y).length, 0);
    bar.innerHTML = `<b>Режим правок</b><span>${n} ${plural(n, ['правка', 'правки', 'правок'])}</span>
      <button data-ecopy ${n ? '' : 'disabled'}>Скопировать</button><button data-edown ${n ? '' : 'disabled'}>Скачать edits.json</button>
      <button data-eclear ${n ? '' : 'disabled'}>Очистить</button>`;
  }
  document.addEventListener('click', e => {
    if (!EDIT) return;
    if (e.target.closest('[data-ecopy]')) {
      const txt = editsJSON();
      const done = () => { e.target.textContent = 'Скопировано ✓'; setTimeout(renderEditBar, 1500); };
      if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(txt).then(done, () => fallbackCopy(txt, done));
      else fallbackCopy(txt, done);
    } else if (e.target.closest('[data-edown]')) {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(new Blob([editsJSON()], { type: 'application/json' }));
      a.download = 'edits.json'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000);
    } else if (e.target.closest('[data-eclear]')) {
      if (!confirm('Удалить все несохранённые правки?')) return;
      EDITS = {}; try { localStorage.removeItem(EDIT_KEY); } catch (err) {}
      applyEdits(); for (const k in cache) delete cache[k]; rerenderView(); renderEditBar();
    }
  });
  function fallbackCopy(txt, done) {
    const ta = document.createElement('textarea'); ta.value = txt; document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); done(); } catch (err) {} ta.remove();
  }
  modal.addEventListener('click', e => {
    const eb = EDIT && e.target.closest('[data-eday],[data-eremove],[data-ereset]');
    if (eb) return editWork(current.g.items[current.i], eb);
    if (e.target.closest('.editpanel')) return;
    if (e.target.closest('[data-close]')) return closeModal();
    if (e.target.closest('[data-prev]')) return openWork(current.g.ctx, current.i - 1);
    if (e.target.closest('[data-next]')) return openWork(current.g.ctx, current.i + 1);
    if (e.target.closest('a[href^="#"]')) { closeModal(); return; }            // chip / participant link → navigate
    if (e.target.matches('[data-stage], .modal__foot, .modal__head')) closeModal(); // click outside the work
  });
  document.addEventListener('keydown', e => {
    if (modal.hidden) return;
    if (e.key === 'Escape') closeModal();
    else if (e.key === 'ArrowLeft') openWork(current.g.ctx, current.i - 1);
    else if (e.key === 'ArrowRight') openWork(current.g.ctx, current.i + 1);
  });
  let touchX = null;
  modal.addEventListener('touchstart', e => { touchX = e.touches[0].clientX; }, { passive: true });
  modal.addEventListener('touchend', e => {
    if (touchX == null || !current) return;
    const dx = e.changedTouches[0].clientX - touchX; touchX = null;
    if (Math.abs(dx) > 60) openWork(current.g.ctx, current.i + (dx < 0 ? 1 : -1));
  });
  document.addEventListener('click', e => {
    const t = e.target.closest('.tile');
    if (t) openWork(+t.dataset.ctx, +t.dataset.i);
  });

  /* ------------------------------------------------------------ router */
  let route = {};
  function parse() {
    const [year, section, sub] = location.hash.replace(/^#\/?/, '').split('/');
    const y = D.years[year] ? year : D.site.defaultYear;
    // sections can be switched off per year (year.json → disabledSections); then the first available one opens
    const off = D.years[y].disabledSections || [];
    const open = SECTIONS.filter(x => !off.includes(x));
    const s = open.includes(section) ? section : (open.includes('days') ? 'days' : open[0]);
    return { year: y, section: s, sub: sub ? decodeURIComponent(sub) : null };
  }
  function render() {
    const prev = route;
    route = parse();
    closeModal();
    const cfg = D.years[route.year];
    applyYearTheme(cfg);
    document.title = `${cfg.title} — ${T.nav[route.section]}`;
    renderTopbar(route.year, route.section);
    const samePage = prev.year === route.year && prev.section === route.section;
    if (!samePage) {
      renderYearhead(route.year, route.section);
      buildView();
    }
    if (route.sub) {
      const id = (route.section === 'participants' ? 'p-' : 'd-') + route.sub;
      const el = document.getElementById(id);
      if (el) requestAnimationFrame(() => el.scrollIntoView({ block: 'start' }));
    } else if (!samePage && prev.year) {
      const head = $('#secbar-sentinel');
      if (head && window.scrollY > head.offsetTop - 44) window.scrollTo({ top: head.offsetTop - 44 });
    }
  }
  function buildView() {
    galleries.length = 0;
    const view = $('#view');
    view.className = 'view';
    view.innerHTML = { days: viewDays, participants: viewParticipants, prompts: viewPrompts, rules: viewRules }[route.section](route.year);
    mountGalleries(view);
  }
  function rerenderView() {        // after edits: rebuild the page and keep the scroll position
    const y = window.scrollY;
    renderYearhead(route.year, route.section);
    buildView();
    window.scrollTo(0, y);
  }
  window.addEventListener('hashchange', render);
  renderFooter();
  render();
  renderEditBar();
})();
